<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']=='POST'){ $t=mysqli_real_escape_string($conn,$_POST['title']);$type=mysqli_real_escape_string($conn,$_POST['type']);$dt=$_POST['schedule'];$cap=(int)$_POST['capacity'];$link=mysqli_real_escape_string($conn,$_POST['stream']);$desc=mysqli_real_escape_string($conn,$_POST['description']); mysqli_query($conn,"INSERT INTO classes(trainer_id,title,class_type,schedule_datetime,capacity,stream_link,description) VALUES(1,'$t','$type','$dt',$cap,'$link','$desc')"); }
$classes=mysqli_query($conn,"SELECT c.*,u.full_name trainer FROM classes c LEFT JOIN trainers tr ON c.trainer_id=tr.id LEFT JOIN users u ON tr.user_id=u.id ORDER BY schedule_datetime"); ?>
<!DOCTYPE html><html><head><title>Classes</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Class Schedule Management</h1><form class="form" method="post"><div class="two"><div><label>Title</label><input name="title" required></div><div><label>Type</label><input name="type" required></div></div><div class="two"><div><label>Schedule</label><input name="schedule" type="datetime-local" required></div><div><label>Capacity</label><input name="capacity" type="number" required></div></div><label>Video/Stream Link</label><input name="stream" placeholder="https://www.youtube.com/embed/..."><label>Description</label><textarea name="description"></textarea><button>Add Class</button></form><br><table class="table"><tr><th>Title</th><th>Type</th><th>Trainer</th><th>Schedule</th><th>Capacity</th></tr><?php while($r=mysqli_fetch_assoc($classes)):?><tr><td><?=e($r['title'])?></td><td><?=e($r['class_type'])?></td><td><?=e($r['trainer'])?></td><td><?=$r['schedule_datetime']?></td><td><?=$r['capacity']?></td></tr><?php endwhile;?></table></main></div></body></html>
